        local env = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
        if env then
            self.rewardEnv = env
        end
    end
end

function OverseaManageCookingListRightPanelNode:AddUIClick()
    SetButtonAction(self.BtnCooking.gameObject,Bind(self,self.OnBtnCookingClick))
    SetButtonAction(self.BtnStar.gameObject,Bind(self,self.OnBtnStarClick))
    SetButtonAction(self.BtnMax.gameObject,Bind(self,self.OnBtnMaxClick))
    SetButtonAction(self.BtnMini.gameObject,Bind(self,self.OnBtnMiniClick))
end

function OverseaManageCookingListRightPanelNode:ShowRightInfo(data,cellIndex)
    self.data = data
    self.cellIndex = cellIndex
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local serverInfo =maidCoffeePlayerComponent:GetRecipeDoJoById(data.refId)


    if not isNull(serverInfo) then
        self:SetInfoShow(serverInfo)
        self:SetWeight()
    else
        self:SetLockStatus()
    end
end

function OverseaManageCookingListRightPanelNode:SetLockStatus()
    self:SetStatus(false)
    local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.refId)
    local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(foodVo.jumpAway[1])
    local source = parse_localizeText(row,"source")
    if not isNull(source) then
        local desc = string.gsub(source, "\\n", "\n")
        CfUtils.FillText(self.TxtLock,desc)
    end
    CfUtils.FillText(self.TxtName,foodVo.name)
    CfUtils.SetUISwitchText(self.TxtName,2)
    self.BtnCooking:ResetFontStyle("B3", localize("前往获取"))
end
