function OverseaManageCookingListRightPanelNode:SetInfoShow(serverInfo)
    self:SetStatus(true)
    self:SetFoodInfo()
    self:SetIsCollect(serverInfo.isCollect)
    self:SetNeedFood()
    self:SetCalculation()
    ---这里是设置已经解锁的状态
    self:SetBtnCookStatus(1)
    if not isNull(self.data.curInputNum) then
        self:OnCalculationClick(self.data.curInputNum)
    else
        self:OnCalculationClick(1)
    end
end

function OverseaManageCookingListRightPanelNode:SetBtnCookStatus(curNum)
    local canMakeNum = MaidCoffeeUtils.CalculationCanMakeFoodCount(self.data)
    if canMakeNum >= curNum then
        self.BtnCooking:ResetFontStyle("B1", localize("制作"))
    else
        self.BtnCooking:ResetFontStyle("B17", localize("制作"))
    end
end

---设置权重显示
function OverseaManageCookingListRightPanelNode:SetWeight()
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local recipeDojo = maidCoffeePlayerComponent:GetRecipeDoJoById(self.data.refId)
    if recipeDojo then
        local recipeInfo = maidCoffeePlayerComponent:GetRecipeInfoByExp(self.data.refId,recipeDojo.exp)
        if recipeInfo.isToMax then
            local str = string.gsub(localize("出色发挥：料理数量*<color=#32ffe4>_num_</color>",{_num_ = math.floor(tonumber(self.data.piece[2]))}),"\\n","\n")
            CfUtils.FillText(self.TipContent1,str)
            str =  string.gsub(localize("超常发挥：料理数量*<color=#32ffe4>_num_</color>",{_num_ = math.floor(tonumber(self.data.piece[3]))}),"\\n","\n")
            CfUtils.FillText(self.TipContent2,str)
        else
            local bigAdd = math.floor(tonumber(self.data.experienceAdd[2])/tonumber(self.data.experienceAdd[1])) * 100
            local bBigAdd = math.floor(tonumber(self.data.experienceAdd[3])/tonumber(self.data.experienceAdd[1])) * 100
            local str = string.gsub(localize("出色发挥：食谱经验*<color=#32ffe4>_num_%</color>",{_num_ = bigAdd}),"\\n","\n")
            CfUtils.FillText(self.TipContent1,str)
            str = string.gsub(localize("超常发挥：食谱经验*<color=#32ffe4>_num_%</color>",{_num_ = bBigAdd}),"\\n","\n")
            CfUtils.FillText(self.TipContent2,str)
        end
    end
end

function OverseaManageCookingListRightPanelNode:SetFoodInfo()
    local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.foodId)
    if not isNull(foodVo) then
        CfUtils.FillText(self.TxtName,foodVo.name)
        local desc = string.gsub(foodVo.desc, "\\n", "\n")
        CfUtils.FillText(self.TxtContent,desc)
        CfUtils.SetUISwitchText(self.TxtName,1)
        CfUtils.FillImage(self.ImgIconFood.gameObject,foodVo.photoPath)
    end
    CfUtils.FillText(self.TxtGetNumber,GoodsUtils.GetThingNo(self.data.foodId))
end

function OverseaManageCookingListRightPanelNode:SetNeedFood()
    self.canMakeMax = nil
    local rewards = {}
    for i = 1, #self.data.foodStuff do
        table.insert(rewards,{goodsId = tonumber(self.data.foodStuff[i]),goodsNum = tonumber(self.data.foodStuffNum[i]) })
    end
    self.rewardEnv:FreshBaseUI(rewards,false,false,true,true,true)

    for i = 1, #self.data.foodStuff do
        local needId = tonumber(self.data.foodStuff[i])
        local needNum = tonumber(self.data.foodStuffNum[i])
        local haveNum = GoodsUtils.GetThingNo(needId)
        ---计算一下最大能做多少个
        local makeNum = math.floor(haveNum/needNum)
        if makeNum ~= 0 then
            if not isNull(self.canMakeMax) then
                if makeNum < self.canMakeMax then
                    self.canMakeMax = makeNum
                end
            else
                self.canMakeMax = makeNum
            end
        end
    end
end

function OverseaManageCookingListRightPanelNode:RefreshCanMakeMax()
    self.canMakeMax = nil
    for i = 1, #self.data.foodStuff do
        local needId = tonumber(self.data.foodStuff[i])
        local needNum = tonumber(self.data.foodStuffNum[i])
        local haveNum = GoodsUtils.GetThingNo(needId)
        ---计算一下最大能做多少个
        local makeNum = math.floor(haveNum/needNum)
        if makeNum ~= 0 then
            if not isNull(self.canMakeMax) then
                if makeNum < self.canMakeMax then
                    self.canMakeMax = makeNum
                end
            else
                self.canMakeMax = makeNum
            end
        else
            self.canMakeMax = 0
        end
    end

    if self.data.curInputNum > checkNumber(self.canMakeMax) then
        self.data.curInputNum = checkNumber(self.canMakeMax) ~= 0 and checkNumber(self.canMakeMax) or 1
    end

end

---制作数量
function OverseaManageCookingListRightPanelNode:RefreshNumShow(node,_haveNum,needNum,makeNum)
    local needNum = needNum
    local haveNum = _haveNum
    local str = haveNum
    if haveNum < needNum * makeNum then
        str = string.format("<color=#ff6767>%s</color>",haveNum)
    end
    CfUtils.FillText(node,str.."/"..needNum * makeNum)
end

function OverseaManageCookingListRightPanelNode:SetCalculation()
    if self.calculationEvn then
        local maxNum = 1
        if not isNull(self.canMakeMax) then
            maxNum = self.canMakeMax
        end
        self.calculationEvn:SetParams(Bind(self,self.OnCalculationClick),self.data.curInputNum or 1,1,maxNum,localize("当前已达最大份数"))
    end
end

function OverseaManageCookingListRightPanelNode:RefreshPriceShow(exp)
    local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    CfUtils.FillImage(self.ImgGoodsIcon,goodsVo.photoPath)
    ---@type MaidCoffeePlayerComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local recipeInfo = component:GetRecipeInfoByExp(self.data.refId,self.data.cacheExp)
    local price = self.data:GetPrice(recipeInfo.rating)
    CfUtils.FillText(self.TextNumber,price)
end

function OverseaManageCookingListRightPanelNode:OnCalculationClick(makeNum)
    self.data.curInputNum = makeNum

    local rewards = {}
    for i = 1, #self.data.foodStuff do
        table.insert(rewards,{goodsId = tonumber(self.data.foodStuff[i]),goodsNum = tonumber(self.data.foodStuffNum[i]) * makeNum })
    end
    self.rewardEnv:FreshBaseUI(rewards,false,false,true,true,true)


    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local recipeDojo = maidCoffeePlayerComponent:GetRecipeDoJoById(self.data.refId)
    local makeGetExp = tonumber(self.data.experienceAdd[1]) * makeNum + recipeDojo.exp
    if self.cookingCb then
        self.cookingCb(makeGetExp)
    end

end

function OverseaManageCookingListRightPanelNode:SetIsCollect(isCollect)
    self.ImgStar.Status = isCollect == 1 and 2 or 1
end

function OverseaManageCookingListRightPanelNode:SetStatus(status)
    KTool.SetActive(self.FoodNode.gameObject,status)
    KTool.SetActive(self.ChooseNode.gameObject,status)
    KTool.SetActive(self.NormalNode.gameObject,status)
    KTool.SetActive(self.BtnStar.gameObject,status)
    KTool.SetActive(self.LockNode.gameObject,not status)
    KTool.SetActive(self.TipsNode.gameObject,status)
end

function OverseaManageCookingListRightPanelNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

---click start--------------------------------
---烹饪
---M
--result--int--结果，1成功，2大成功，3超大成功
--exp--int--总熟练度
--rating--int--评级
--rewards--list--奖励列表
function OverseaManageCookingListRightPanelNode:OnBtnCookingClick()
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local serverInfo =maidCoffeePlayerComponent:GetRecipeDoJoById(self.data.refId)
    if not isNull(serverInfo) then
        local canMakeNum = MaidCoffeeUtils.CalculationCanMakeFoodCount(self.data)
        if canMakeNum > 0 then
            local curInputNum = self.calculationEvn:GetInputNum() or 1
            if canMakeNum >= curInputNum then
                GameUtils.Request(Interfaces.MaidCoffeeCooking,
                        {recipeId = self.data.refId,cookNum = curInputNum},
                        function(request,response)
                            if checkInt(response.errCode) == 0 then
                                cs_coroutine.start(function()
                                    UIRaycastBlocker:AddCondition("OverseaManageCookingListRightPanelNode")
                                    self.RightAni:Play("OverseaManageCookingListMainDialog_Cooking")
                                    coroutine.yield(Yielders.GetWaitForSeconds(0.55))
                                    CfUtils.SetActive(self.UIFX_Idle.gameObject,false)
                                    local costData = self:GetCostData(curInputNum)
                                    GoodsUtils.DrawRewards(costData, false)
                                    UIRaycastBlocker:RemoveCondition("OverseaManageCookingListRightPanelNode")
                                    UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaCookingMakeResult, parameters = {
                                        localData = clone(self.data),serverData = response.data,makeNum = response.data.makeNum,callBack =
                                        function(isToMax)
                                            if not isToMax then
                                                maidCoffeePlayerComponent:UpdateThingNo(self.data.refId,{isCollect = serverInfo.isCollect,exp = response.data.exp,rating = response.data.rating })
                                            end
                                        end,closeCallBack = function()
                                            CfUtils.SetActive(self.UIFX_Idle.gameObject,true)
                                            self:RefreshCanMakeMax()
                                            self:SetCalculation()
                                            if self.cookingSuccessCb then
                                                self.cookingSuccessCb()
                                            end
                                    end}})
                                end)
                            end
                        end)
            else
                GameUtils.Toast(localize("所需食材不足"))
            end
        else
            GameUtils.Toast(localize("所需食材不足"))
        end
    else
        local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.refId)
        if not isNull(foodVo) then
            if isSet(foodVo, "jumpAway") and table.count(foodVo.jumpAway) > 0 then
                local goodsConfMgr = GoodsConfMgr:GetInstance()
                local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                local canJump = goodsConfMgr:CheckIsCanJump(row)
                if canJump then
                    if isSet(foodVo,"jumpParameter") then
                        local type = GoodsUtils.GetIdType(foodVo.jumpParameter[1], Constants.IDArea.Quests)
                        if type == Constants.IDType.QuestRegion then
                            local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
                            local isUnLock,str  =  ActionUtils.IsUnlockRegionQuest(foodVo.jumpParameter[1])
                            if isUnLock then
                                local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                                goodsConfMgr:ExecuteJump(row, {},nil,nil,{foodVo.jumpParameter[1]})
                            else
                                GameUtils.Toast(str)
                            end
                        else
                            local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                            goodsConfMgr:ExecuteJump(row, {})
                        end
                    else
                        local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
                        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.fishId)
                        if goodsVo then
                            goodsConfMgr:ExecuteJump(row, goodsVo)
                        else
                            goodsConfMgr:ExecuteJump(row, {})
                        end
                    end
                end
            else
                printError("id %s  不能前往跳转 没有配置openType",foodVo.id)
            end
        end
    end
end

function OverseaManageCookingListRightPanelNode:GetCostData(num)
    local costData = {}
    if self.data then
        for i = 1, NeedFoodCount do
            if i <= #self.data.foodStuff then
                local needId = tonumber(self.data.foodStuff[i])
                table.insert(costData,{goodsId = needId,num = tonumber(self.data.foodStuffNum[i]) * - num})
            end
        end
    end
    return costData
end

---收藏
function OverseaManageCookingListRightPanelNode:OnBtnStarClick()
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local serverInfo =maidCoffeePlayerComponent:GetRecipeDoJoById(self.data.refId)
    if not isNull(serverInfo) then
        local _type = (serverInfo.isCollect == 1) and 2 or 1
        GameUtils.Request(Interfaces.MaidCoffeeCookCollect,
                {recipeId = self.data.refId,type = _type},
                function()
                    local isCollect = (serverInfo.isCollect == 1) and 0 or 1
                    if isCollect == 1 then
                        GameUtils.Toast(localize("已置顶食谱"))
                    end
                    maidCoffeePlayerComponent:UpdateThingNo(self.data.refId, {isCollect = isCollect,exp = serverInfo.exp,rating = serverInfo.rating })
                    self:SetIsCollect(isCollect)
                    if self.collectCb then
                        self.collectCb(self.cellIndex)
                    end
                end)
    end
end

function OverseaManageCookingListRightPanelNode:OnBtnMaxClick()
    local canMakeNum = MaidCoffeeUtils.CalculationCanMakeFoodCount(self.data)
    local num = canMakeNum > 0 and canMakeNum or 1
    self.calculationEvn:SetInputText(num)
    self:SetBtnCookStatus(num)
end

function OverseaManageCookingListRightPanelNode:OnBtnMiniClick()
    self.calculationEvn:SetInputText(1)
    self:SetBtnCookStatus(1)
end
